<script setup lang="ts">
const {t}=useI18n(),{bizErrorMessage}=useBizError(),staff=useStaffStore(),warehouses=useWarehouseStore()
const ready=ref(false)
const appliedFilters=ref<Record<string,any>>({})
const warehouseId=computed(()=>warehouses.currentWarehouse?.id||null),canEdit=computed(()=>ready.value&&!!staff.refreshed&&!!staff.staffInfo&&staff.hasPermission('freight_edit'))
const route=useRoute()
const filters=reactive(Object.fromEntries(['carrier_id','start_date','end_date','country','state'].map(key=>[key,String(route.query[key]||'')])) as Record<'carrier_id'|'start_date'|'end_date'|'country'|'state',string>),carriers=ref<any[]>([]),tab=ref('shipments'),page=ref(1)
const data=ref<any>(null),loading=ref(false),error=ref('')
const countries=ref<string[]>([]),exporting=ref(false)
const states=['unbilled','no_estimate','currency_mismatch','matched','difference','accepted','disputed']
const params=()=>Object.fromEntries(Object.entries({...filters,...(tab.value==='invoices'?{country:'',state:''}:{}),page:page.value,per_page:20}).filter(([,value])=>value!==''))
const exportReport=async(format:string)=>{if(exporting.value||loading.value||!data.value)return;exporting.value=true;error.value='';try{const query=new URLSearchParams(Object.fromEntries(Object.entries({...appliedFilters.value,start_date:data.value.start_date,end_date:data.value.end_date,format}).map(([key,value])=>[key,String(value)])));await downloadFile('/api/warehouse/carrier/freight/report/export?'+query,{headers:warehouseHeaders(warehouseId.value)},'freight.'+format)}catch(e){error.value=bizErrorMessage(e as HttpRequestError)}finally{exporting.value=false}}
const carrierError=ref(''),carriersLoading=ref(false)
let carrierGeneration=0,disposed=false
const loadCarriers=async()=>{const seq=++carrierGeneration;carriersLoading.value=true;carrierError.value='';const result=await httpRequest<any>('/api/warehouse/carrier/freight/carriers',{headers:warehouseHeaders(warehouseId.value),onError:e=>{if(seq===carrierGeneration)carrierError.value=bizErrorMessage(e)}});if(seq!==carrierGeneration||disposed)return;carriers.value=result?.items||[];carriersLoading.value=false}
let generation=0
const load=async()=>{if(!ready.value)return;const requestParams=params();const seq=++generation;data.value=null;error.value='';loading.value=true;const result=await httpRequest<any>('/api/warehouse/carrier/freight/'+(tab.value==='invoices'?'invoices':'report'),{params:requestParams,headers:warehouseHeaders(warehouseId.value),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;if(result)appliedFilters.value=requestParams;if(result?.countries)countries.value=result.countries;loading.value=false}}
const chartFilter=(key:string,value:string)=>{if(key==='carrier_id')filters.carrier_id=value;else if(key==='country')filters.country=value;search()};
const allInvoices=()=>{filters.start_date=data.value?.start_date||filters.start_date;filters.end_date=data.value?.end_date||filters.end_date;tab.value='invoices'}
const search=()=>{if(page.value!==1)page.value=1;else load()}
watch([warehouseId,tab],search);watch(page,load)
watch(()=>route.query,()=>{for(const key of Object.keys(filters) as (keyof typeof filters)[])filters[key]=String(route.query[key]||'');search()})
const initialize=async()=>{ready.value=false;loading.value=true;error.value='';data.value=null;const current=await staff.getCurrentStaffInfo();if(disposed)return;if(!current){loading.value=false;error.value=t('action-results.failed');return}warehouses.syncWarehouses();ready.value=true;await Promise.all([loadCarriers(),load()])};onMounted(initialize);onBeforeUnmount(()=>{disposed=true;generation++;carrierGeneration++})
const columns=computed(()=>tab.value==='invoices'?[
 {key:'invoice_number',label:t('freight.number')},{key:'carrier_name',label:t('nav.carrier')},{key:'invoice_date',label:t('freight.date')},{key:'period',label:t('freight.period')},{key:'total',label:t('freight.amount'),type:'qty' as const},{key:'unresolved',label:t('freight.unresolved'),type:'qty' as const},{key:'status',label:t('common.fields.status')}
]:[{key:'dn_id',label:t('nav.DN')},{key:'tracking_number',label:t('freight.tracking'),wrap:true},{key:'carrier_name',label:t('nav.carrier')},{key:'shipping_date',label:t('freight.shipping-date')},{key:'destination_country',label:t('freight.country')},{key:'weights',label:t('freight.weights'),wrap:true},{key:'estimated_amount',label:t('freight.estimate'),type:'qty' as const},{key:'billed',label:t('freight.amount'),type:'qty' as const},{key:'difference',label:t('freight.difference'),type:'qty' as const},{key:'state',label:t('common.fields.status')},{key:'invoices',label:t('freight.invoice'),wrap:true}])
useHead({title:()=>t('freight.title')})
</script>
<template><div class="freight-page w-scope"><header><div><h1>{{t('freight.title')}}</h1><p>{{t('freight.report-hint')}}</p></div><div class="header-actions"><WButton v-if="tab==='shipments'" :disabled="!data||loading||exporting" @click="exportReport('csv')">CSV</WButton><WButton v-if="tab==='shipments'" :disabled="!data||loading||exporting" @click="exportReport('xlsx')">Excel</WButton><WButton v-if="canEdit" to="/freight/import" variant="primary" icon="upload">{{t('freight.import')}}</WButton></div></header>
 <form class="filters" @submit.prevent="search"><WSelect v-model="filters.carrier_id" :aria-label="t('nav.carrier')" :options="[{value:'',label:t('freight.all-carriers')},...carriers.map(row=>({value:String(row.id),label:row.name}))]"/><label>{{t(tab==='invoices'?'freight.period-from':'freight.from')}}<WInput v-model="filters.start_date" type="date"/></label><label>{{t(tab==='invoices'?'freight.period-to':'freight.to')}}<WInput v-model="filters.end_date" type="date"/></label><WSelect v-if="tab==='shipments'" v-model="filters.country" :aria-label="t('freight.country')" :options="[{value:'',label:t('freight.all-countries')},...countries.map(value=>({value,label:value}))]"/><WSelect v-if="tab==='shipments'" v-model="filters.state" :aria-label="t('common.fields.status')" :options="[{value:'',label:t('common.status.all')},...states.map(value=>({value,label:t('freight.states.'+value)}))]"/><WButton type="submit" :loading="loading">{{t('common.search')}}</WButton></form>
 <WSegmented v-model="tab" :label="t('freight.title')" :options="[{value:'shipments',label:t('freight.shipments')},{value:'invoices',label:t('freight.invoices')}]"/>
 <WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="ready?load():initialize()">{{t('dn.list.retry')}}</WButton></template></WAlert><WAlert v-if="carrierError" tone="block" :title="carrierError"><template #actions><WButton :disabled="carriersLoading" @click="loadCarriers">{{t('dn.list.retry')}}</WButton></template></WAlert>
 <p class="scope-note">{{t('freight.scope-hint')}}</p>
 <FreightInvoiceSummary v-if="tab==='shipments'&&data?.invoice_summary" :data="data.invoice_summary" @all="allInvoices"/>
 <WCard v-if="tab==='shipments'&&data" flush><div class="summary-counts"><div><small>{{t('freight.shipments')}}</small><strong>{{data.total}}</strong></div><div v-for="key in ['matched','difference','unbilled','disputed']" :key="key"><small>{{t('freight.states.'+key)}}</small><strong>{{data.states?.[key]??0}}</strong></div></div></WCard>
 <section v-if="data?.totals" class="totals"><WCard v-for="(value,unit) in data.totals" :key="unit"><h2>{{unit}}</h2><template v-if="tab==='invoices'"><small>{{t('freight.amount')}}</small><strong>{{value}}</strong></template><template v-else><div class="currency-totals"><div><small>{{t('freight.estimate')}}</small><strong>{{Number(value.estimate_count)>0?value.estimate:'\u2014'}}</strong></div><div><small>{{t('freight.amount')}}</small><strong>{{Number(value.billed_count)>0?value.billed:'\u2014'}}</strong></div><div><small>{{t('freight.comparable-estimate')}}</small><strong>{{Number(value.comparable_count)>0?value.comparable_estimate:'\u2014'}}</strong></div><div><small>{{t('freight.comparable-billed')}}</small><strong>{{Number(value.comparable_count)>0?value.comparable_billed:'\u2014'}}</strong></div><div><small>{{t('freight.difference')}}</small><strong>{{Number(value.comparable_count)>0?(Number(value.comparable_billed)-Number(value.comparable_estimate)).toLocaleString(undefined,{maximumFractionDigits:2}):'\u2014'}}</strong></div></div></template></WCard></section>
 <FreightDistribution v-if="tab==='shipments'&&data?.distributions" :data="data.distributions" @filter="chartFilter"/>
 <WCard flush><p v-if="data?.start_date" class="period">{{data.start_date}} — {{data.end_date}}</p><WTable :columns="columns" :rows="data?.items||[]" :row-key="tab==='invoices'?'id':'dn_id'" :loading="loading" inset>
 <template #cell-invoice_number="{row}"><NuxtLink :to="'/freight/invoices/'+row.id">{{row.invoice_number}}</NuxtLink></template>
 <template #cell-period="{row}">{{row.period_from}} — {{row.period_to}}</template>
 <template #cell-total="{row}">{{row.currency}} {{row.total}}</template>
 <template #cell-status="{row}"><WStatus :tone="row.status==='confirmed'?'ok':'warn'">{{t('freight.states.'+row.status)}}</WStatus></template>
 <template #cell-dn_id="{row}"><NuxtLink v-if="staff.refreshed&&staff.staffInfo&&staff.hasPermission('dn_read')" :to="'/dn/detail/'+row.dn_id">DN #{{row.dn_id}}</NuxtLink><span v-else>DN #{{row.dn_id}}</span><small class="order-number">{{row.order_number}}</small></template>
 <template #cell-weights="{row}"><span>{{t('freight.actual-weight')}}: {{row.actual_weight??'\u2014'}} kg</span><small class="weight-line" v-for="invoice in row.invoices" :key="invoice.id">{{invoice.invoice_number}}: {{row.billed_weights[invoice.id]??'\u2014'}} kg</small><small class="weight-line" v-if="row.package_count">{{t('freight.box-count',{count:row.package_count})}}</small></template>
 <template #cell-estimated_amount="{row}">{{row.estimated_amount??'—'}} {{row.estimated_currency||''}}</template>
 <template #cell-difference="{row}">{{row.difference??'—'}}</template>
 <template #cell-billed="{row}"><div v-for="(amount,currency) in row.billed" :key="currency">{{currency}} {{amount}}</div><span v-if="!Object.keys(row.billed).length">—</span></template>
 <template #cell-state="{row}"><WStatus :tone="row.state==='matched'?'ok':'warn'">{{t('freight.states.'+row.state)}}</WStatus></template>
 <template #cell-invoices="{row}"><NuxtLink v-for="invoice in row.invoices" :key="invoice.id" class="invoice-link" :to="'/freight/invoices/'+invoice.id">{{invoice.invoice_number}} &middot; {{t('freight.states.'+invoice.status)}}</NuxtLink></template>
 </WTable><div class="pager"><WPagination v-model:page="page" :total="data?.total||0" :page-size="20" show-total/></div></WCard></div></template>
<style scoped>.freight-page h1,.freight-page header>div,.summary>div{min-width:0;max-width:100%;overflow-wrap:anywhere}.freight-page :deep(.w-table td){max-width:260px;white-space:normal;overflow-wrap:anywhere}.summary-counts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));padding:20px;gap:20px}.summary-counts>div+div{border-left:1px solid var(--w-line);padding-left:20px}@media(max-width:767px){.summary-counts{grid-template-columns:repeat(2,minmax(0,1fr))}.summary-counts>div+div{padding-left:0;border:0}}.header-actions{display:flex;gap:8px;flex-wrap:wrap}.order-number,.weight-line{display:block;font-size:12px;line-height:18px}.freight-page :deep(table){min-width:1120px}.freight-page{display:flex;flex-direction:column;gap:20px}header{display:flex;align-items:start;justify-content:space-between;gap:12px}h1{font-size:24px;margin:0 0 8px}h2{font-size:16px;margin:0 0 16px}p,small{color:var(--w-text-3)}header p,.scope-note{margin:0}.filters>.w-select{width:180px;flex:0 1 180px}.header-actions{flex-shrink:0}header>div:first-child{min-width:0}header p{max-width:78ch}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px}.filters>label{display:flex;flex-direction:column;gap:6px;font-size:12px}.totals{display:flex;flex-wrap:wrap;gap:12px}.totals>.w-card{flex:1;min-width:220px}.currency-totals{display:flex;flex-wrap:wrap;gap:24px}strong{display:block;font-size:20px;margin-top:8px}.pager,.period{padding:16px}.invoice-link{display:block}a{color:var(--w-pri)}@media(max-width:767px){header{flex-direction:column}.filters>*,.filters>.w-select{flex:1;min-width:130px;width:auto}}</style>
